use gram_panchayat;
show tables;
select * from citizen;
select * from certificate_type;
select * from certificate_application;
select * from panchayat_office;
select application_date from certificate_application where application_date=(select max(application_date) from certificate_application);
select application_date from certificate_application where application_date=(select min(application_date) from certificate_application);
select application_id from  certificate_application where application_date=(select max(application_date) from certificate_application);
select application_id from certificate_application where application_date=(select min(application_date) from certificate_application);
select * from citizen where citizen_id in (select citizen_id from certificate_application where application_status='approved');
select  * from certificate_application where application_date >(select min(application_date) from certificate_application);
select * from certificate_application where application_date<(select max(application_date) from certificate_application);
select * from citizen where citizen_id in (select citizen_id from certificate_application);
select * from citizen where citizen_id not in(select citizen_id from certificate_application where application_status='approved');
select * from certificate_type where certificate_type_id in (select certificate_id from certificate_application where application_status='approved');
select* from certificate_type where certificate_type_id not in(select certificate_id from certificate_application where application_status='approved');
select* from certificate_application where application_date >(select avg(application_date) from certificate_application);
select c.certificate_name,a.application_date from certificate_application a join certificate_type c on a.certificate_id=c.certificate_type_id where a.application_date=(select max(application_date) from certificate_application);
select certificate_id,count(*) as total_applications from certificate_application group by certificate_id order by total_applications desc limit 1;
select office_id,count(*) as total_applications from certificate_application group by office_id order by total_applications desc limit 1;
select certificate_id,count(*) as total_applications from certificate_application group by certificate_id having count(*)>(select avg(total) from (select count(*) as total from certificate_application group by certificate_id) as x);
select office_id,count(*) as total_applications from panchayat_office group by office_id having count(*)>any(select count(*) from panchayat_office group by office_id);
select office_id,count(*) as total_applications from panchayat_office group by office_id having count(*)>all(select count(*) from panchayat_office group by office_id);
select c.certificate_name from certificate_type c join certificate_application a on c.certificate_type_id=a.certificate_id where a.application_date=(select max(application_date) from certificate_application);
select citizen_id,count(*) as total_applications from certificate_application group by citizen_id having count(*)>1;
select application_status,count(*) as total_applications from certificate_application group by application_status order by total_applications desc limit 1;